using ResearchTrack.BuildingBlocks.Api.Contracts;
using ResearchTrack.BuildingBlocks.Api.Exceptions;
using ResearchTrack.ProjectService.Domain;

namespace ResearchTrack.ProjectService.Features.Projects;

internal static class ProjectMilestonePolicy
{
    private static readonly HashSet<string> AllowedStatuses =
        new(StringComparer.Ordinal)
        {
            ProjectMilestoneStatuses.Planned,
            ProjectMilestoneStatuses.InProgress,
            ProjectMilestoneStatuses.Completed,
            ProjectMilestoneStatuses.Missed,
            ProjectMilestoneStatuses.Cancelled
        };

    private static readonly HashSet<string> OpenStatuses =
        new(StringComparer.Ordinal)
        {
            ProjectMilestoneStatuses.Planned,
            ProjectMilestoneStatuses.InProgress
        };

    private static readonly HashSet<string> TerminalStatuses =
        new(StringComparer.Ordinal)
        {
            ProjectMilestoneStatuses.Completed,
            ProjectMilestoneStatuses.Missed,
            ProjectMilestoneStatuses.Cancelled
        };

    public static string NormalizeAndValidateStatus(string? rawStatus)
    {
        if (string.IsNullOrWhiteSpace(rawStatus))
        {
            ThrowValidation(
                "status",
                "Milestone status is required.");
        }

        var normalized = rawStatus!.Trim().ToUpperInvariant();

        if (!AllowedStatuses.Contains(normalized))
        {
            ThrowValidation(
                "status",
                "Milestone status is invalid.");
        }

        return normalized;
    }

    public static void ValidateDueDateForStatus(
        DateOnly dueDate,
        string status,
        DateOnly today)
    {
        if (OpenStatuses.Contains(status) && dueDate < today)
        {
            ThrowValidation(
                "dueDate",
                "Open milestones must use today or a future due date.");
        }
    }

    public static void ValidateStatusTransition(
        string currentStatus,
        string nextStatus)
    {
        if (string.Equals(
                currentStatus,
                nextStatus,
                StringComparison.Ordinal))
        {
            return;
        }

        if (string.Equals(
                currentStatus,
                ProjectMilestoneStatuses.Completed,
                StringComparison.Ordinal))
        {
            ThrowValidation(
                "status",
                "Completed milestones cannot be moved to another status.");
        }

        if (TerminalStatuses.Contains(currentStatus) &&
            OpenStatuses.Contains(nextStatus))
        {
            ThrowValidation(
                "status",
                "Terminal milestones cannot move back to open states.");
        }
    }

    public static void ValidateChronologyWithPrevious(
        DateOnly? previousDueDate,
        DateOnly currentDueDate)
    {
        if (previousDueDate is not null &&
            currentDueDate < previousDueDate.Value)
        {
            ThrowValidation(
                "dueDate",
                "Milestone due date must be on or after the previous milestone due date.");
        }
    }

    public static void ValidateChronologyForUpdate(
        IReadOnlyList<ProjectMilestone> milestones,
        Guid targetMilestoneId,
        DateOnly newDueDate)
    {
        var ordered = milestones
            .OrderBy(milestone => milestone.SequenceNo)
            .ToArray();

        var index = Array.FindIndex(
            ordered,
            milestone => milestone.Id == targetMilestoneId);

        if (index < 0)
        {
            return;
        }

        if (index > 0 &&
            newDueDate < ordered[index - 1].DueDate)
        {
            ThrowValidation(
                "dueDate",
                "Milestone due date must be on or after the previous milestone due date.");
        }

        if (index < ordered.Length - 1 &&
            newDueDate > ordered[index + 1].DueDate)
        {
            ThrowValidation(
                "dueDate",
                "Milestone due date must be on or before the next milestone due date.");
        }
    }

    public static int CalculateProgressPercent(
        IReadOnlyCollection<ProjectMilestone> milestones)
    {
        var activeMilestones = milestones
            .Where(milestone =>
                !string.Equals(
                    milestone.Status,
                    ProjectMilestoneStatuses.Cancelled,
                    StringComparison.Ordinal))
            .ToArray();

        if (activeMilestones.Length == 0)
        {
            return 0;
        }

        var completedCount = activeMilestones.Count(milestone =>
            string.Equals(
                milestone.Status,
                ProjectMilestoneStatuses.Completed,
                StringComparison.Ordinal));

        return (int)Math.Round(
            completedCount * 100.0 / activeMilestones.Length,
            MidpointRounding.AwayFromZero);
    }

    public static DateOnly? ComputeProjectMilestoneDate(
        IReadOnlyCollection<ProjectMilestone> milestones)
    {
        var openDueDates = milestones
            .Where(milestone => OpenStatuses.Contains(milestone.Status))
            .Select(milestone => milestone.DueDate)
            .ToArray();

        return openDueDates.Length == 0
            ? null
            : openDueDates.Min();
    }

    public static void ApplyAggregates(
        Project project,
        IReadOnlyCollection<ProjectMilestone> milestones)
    {
        project.ProgressPercent =
            CalculateProgressPercent(milestones);

        project.MilestoneDate =
            ComputeProjectMilestoneDate(milestones);
    }

    private static void ThrowValidation(
        string field,
        string message)
    {
        throw new ApiValidationException([
            new ApiFieldError(field, [message])
        ]);
    }
}

using ResearchTrack.BuildingBlocks.Api.Contracts;
using ResearchTrack.BuildingBlocks.Api.Exceptions;
using ResearchTrack.ProjectService.Contracts;
using ResearchTrack.ProjectService.Domain;

namespace ResearchTrack.ProjectService.Features.Projects;

internal static class ProjectRequestValidator
{
    private const int TitleMaxLength = 40;
    private const int SummaryMaxLength = 250;
    private const int BatchMaxLength = 32;
    private const int SemesterMaxLength = 32;
    private const int MilestoneTitleMaxLength = 40;
    private const int MilestoneDescriptionMaxLength = 250;

    public static NormalizedCreateProject Validate(
        CreateProjectRequest request,
        DateOnly today)
    {
        var errors = new List<ApiFieldError>();
        var title = NormalizeRequired(request.Title, "title", "Title", TitleMaxLength, errors);
        var summary = NormalizeRequired(request.Summary, "summary", "Summary", SummaryMaxLength, errors);
        var batch = NormalizeRequired(request.Batch, "batch", "Batch", BatchMaxLength, errors);
        var semester = NormalizeRequired(request.Semester, "semester", "Semester", SemesterMaxLength, errors);
        ValidateSemester(semester, errors);

        var studentIds = (request.StudentIds ?? []).ToArray();
        if (studentIds.Length == 0)
        {
            errors.Add(new ApiFieldError("studentIds", ["At least one student must be selected."]));
        }
        else if (studentIds.Distinct().Count() != studentIds.Length)
        {
            errors.Add(new ApiFieldError("studentIds", ["Duplicate students are not allowed."]));
        }

        if (request.LeaderStudentId is Guid leaderStudentId
            && !studentIds.Contains(leaderStudentId))
        {
            errors.Add(new ApiFieldError(
                "leaderStudentId",
                ["Leader must be one of the selected students."]));
        }

        var milestoneRequests = request.Milestones ?? [];
        var milestones = new List<NormalizedMilestone>();
        if (milestoneRequests.Count == 0)
        {
            errors.Add(new ApiFieldError("milestones", ["At least one milestone is required."]));
        }
        else
        {
            DateOnly? previousDueDate = null;
            for (var index = 0; index < milestoneRequests.Count; index++)
            {
                var milestone = milestoneRequests[index];
                var prefix = $"milestones[{index}]";
                var milestoneTitle = NormalizeRequired(
                    milestone.Title,
                    $"{prefix}.title",
                    "Milestone title",
                    MilestoneTitleMaxLength,
                    errors);
                var description = milestone.Description?.Trim();
                if (description?.Length > MilestoneDescriptionMaxLength)
                {
                    errors.Add(new ApiFieldError(
                        $"{prefix}.description",
                        [$"Milestone description must not exceed {MilestoneDescriptionMaxLength} characters."]));
                }

                if (milestone.DueDate is null)
                {
                    errors.Add(new ApiFieldError(
                        $"{prefix}.dueDate",
                        ["Milestone due date is required."]));
                    continue;
                }

                var dueDate = milestone.DueDate.Value;
                if (dueDate < today)
                {
                    errors.Add(new ApiFieldError(
                        $"{prefix}.dueDate",
                        ["Milestone due date cannot be in the past."]));
                }

                if (previousDueDate is not null && dueDate < previousDueDate.Value)
                {
                    errors.Add(new ApiFieldError(
                        $"{prefix}.dueDate",
                        ["Milestone due dates must be in chronological order."]));
                }

                previousDueDate = dueDate;
                if (!string.IsNullOrWhiteSpace(milestoneTitle))
                {
                    milestones.Add(new NormalizedMilestone(
                        milestoneTitle,
                        string.IsNullOrWhiteSpace(description) ? null : description,
                        dueDate));
                }
            }
        }

        if (errors.Count > 0)
        {
            throw new ApiValidationException(errors);
        }

        return new NormalizedCreateProject(
            title!,
            summary!,
            batch!,
            semester!,
            studentIds,
            request.LeaderStudentId,
            milestones);
    }

    public static string ValidateSemester(string? value)
    {
        var errors = new List<ApiFieldError>();
        var semester = NormalizeRequired(value, "semester", "Semester", SemesterMaxLength, errors);
        ValidateSemester(semester, errors);

        if (errors.Count > 0)
        {
            throw new ApiValidationException(errors);
        }

        return semester!;
    }

    private static void ValidateSemester(
        string? semester,
        ICollection<ApiFieldError> errors)
    {
        if (!string.IsNullOrWhiteSpace(semester) && !ProjectSemesters.IsSupported(semester))
        {
            errors.Add(new ApiFieldError(
                "semester",
                [$"Semester must be either '{ProjectSemesters.Semester1}' or '{ProjectSemesters.Semester2}'."]));
        }
    }

    public static IReadOnlyList<Guid> ValidateMemberStudentIds(
        AddProjectMembersRequest request)
    {
        var errors = new List<ApiFieldError>();
        var studentIds = (request.StudentIds ?? []).ToArray();

        if (studentIds.Length == 0)
        {
            errors.Add(new ApiFieldError(
                "studentIds",
                ["At least one student must be selected."]));
        }
        else if (studentIds.Distinct().Count() != studentIds.Length)
        {
            errors.Add(new ApiFieldError(
                "studentIds",
                ["Duplicate students are not allowed."]));
        }

        if (errors.Count > 0)
        {
            throw new ApiValidationException(errors);
        }

        return studentIds;
    }

    public static void ValidateResolvedStudents(
        IReadOnlyCollection<Guid> requestedStudentIds,
        IReadOnlyCollection<Guid> resolvedStudentIds)
    {
        var resolved = resolvedStudentIds.ToHashSet();
        var missing = requestedStudentIds
            .Where(id => !resolved.Contains(id))
            .Distinct()
            .ToArray();

        if (missing.Length == 0)
        {
            return;
        }

        throw new ApiValidationException([
            new ApiFieldError(
                "studentIds",
                ["One or more selected students are invalid or are no longer registered as students."])
        ]);
    }

    private static string? NormalizeRequired(
        string? value,
        string field,
        string displayName,
        int maxLength,
        ICollection<ApiFieldError> errors)
    {
        var normalized = value?.Trim();
        var messages = new List<string>();
        if (string.IsNullOrWhiteSpace(normalized))
        {
            messages.Add($"{displayName} is required.");
        }
        else if (normalized.Length > maxLength)
        {
            messages.Add($"{displayName} must not exceed {maxLength} characters.");
        }

        if (messages.Count > 0)
        {
            errors.Add(new ApiFieldError(field, messages));
        }

        return normalized;
    }

    internal sealed record NormalizedCreateProject(
        string Title,
        string Summary,
        string Batch,
        string Semester,
        IReadOnlyList<Guid> StudentIds,
        Guid? LeaderStudentId,
        IReadOnlyList<NormalizedMilestone> Milestones);

    internal sealed record NormalizedMilestone(
        string Title,
        string? Description,
        DateOnly DueDate);
}

